test("exactly at the deadline keeps the raw score", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200000}), {periodsLate: 0, deduction: 0, score: 45});
});

test("one millisecond before the deadline keeps the raw score", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 40, rawScore: 1, deadline: 1704067200000, submittedAt: 1704067199999}), {periodsLate: 0, deduction: 0, score: 1});
});

test("one hour late counts as one period and deducts 5 from 45", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1709257600000, submittedAt: 1709261200000}), {periodsLate: 1, deduction: 5, score: 40});
});

test("49 hours late counts as three periods and deducts 15 from 45", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50.0, rawScore: 45, deadline: 1703980800000, submittedAt: 1704157200000.0}), {periodsLate: 3, deduction: 15, score: 30});
});

test("120 hours and 1 minute late counts as six periods and scores 0", function () {
  var actual = code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1706659200000, submittedAt: 1707091260000});
  assert.equal(actual.periodsLate, 6);
  assert.equal(actual.score, 0);
});

test("exactly 72 hours late counts as three periods and a negative result scores 0", function () {
  var actual = code.applyLatePenalty({maxPoints: 50, rawScore: 10, deadline: 1709257600000, submittedAt: 1709516800000});
  assert.equal(actual.periodsLate, 3);
  assert.equal(actual.score, 0);
});

test("exactly 120 hours late counts as five periods and deducts 25", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1701388800000, submittedAt: 1701820800000}), {periodsLate: 5, deduction: 25, score: 20});
});

test("exactly 24 hours late counts as one period and deducts 8 from 70", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 80, rawScore: 70, deadline: 1709257600000, submittedAt: 1709344000000}), {periodsLate: 1, deduction: 8, score: 62});
});

test("one millisecond after 24 hours counts as two periods and deducts 16", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 80, rawScore: 70, deadline: 1709257600000, submittedAt: 1709344000001}), {periodsLate: 2, deduction: 16, score: 54});
});

test("one millisecond after the deadline counts as one period and the score stays at 0", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 30, rawScore: 3.0, deadline: 3, submittedAt: 4}), {periodsLate: 1, deduction: 3, score: 0});
});

test("one millisecond under 60 hours counts as three periods and deducts 24", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 80, rawScore: 55, deadline: 1706745600000, submittedAt: 1706961599999}), {periodsLate: 3, deduction: 24, score: 31});
});

test("one millisecond over 60 hours counts as three late periods", function () {
  assert.equal(code.countLatePeriods({deadline: 1706745600000, submittedAt: 1706961600001}), 3);
});

test("one millisecond before 120 hours counts as five periods and deducts 40", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 80, rawScore: 70, deadline: 1706659200000, submittedAt: 1707091199999}), {periodsLate: 5, deduction: 40, score: 30});
});

test("one millisecond after 120 hours counts as six periods and scores 0", function () {
  var actual = code.applyLatePenalty({maxPoints: 80, rawScore: 70, deadline: 1706659200000, submittedAt: 1707091200001});
  assert.equal(actual.periodsLate, 6);
  assert.equal(actual.score, 0);
});

test("exactly 96 hours late counts as four periods and deducts 12", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 30, rawScore: 13, deadline: 1706745600000, submittedAt: 1707091200000}), {periodsLate: 4, deduction: 12, score: 1});
});

test("an unknown field throws an error naming that field", function () {
  assert.throws(function () {
    code.applyLatePenalty({maxPoints: 50, hoursLate: 1, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200000});
  }, /^unknown field: hoursLate$/);
});
